const mainTags = [
  "Nivel_Pct", "Nivel_CM", "Nivel_Voltios", "Flow_Voltios",
  "Setpoint_Pct", "Fill_Valve_Pct", "Discharge_Valve_Pct",
  "Fill_Valve_Raw", "Discharge_Valve_Raw", "SP_Display_CM", "PV_Display_CM",
  "PID_Kp", "PID_Ki", "PID_Kd",
  "Modo_Control", "Usar_Pot_FIO", "Descarga_Auto", "Sistema_Activo"
];
const globalTags = ["DI_Start", "DI_Stop", "DI_Modo_Local"];
const reads = [
  ...globalTags.map(t => ({ topic: "ns=6;s=Arp.Plc.Eclr/" + t, action: "read" })),
  ...mainTags.map(t => ({ topic: "ns=6;s=Arp.Plc.Eclr/MainInstance." + t, action: "read" }))
];
return [reads];

const now = Date.now();
const st = global.get("tanque_state") || {
  conectado: false,
  host: "192.168.1.10",
  port: 4840,
  modo: "PID",
  sistema_activo: true,
  di_start: false,
  di_stop: false,
  di_modo_local: false,
  usar_pot_fio: false,
  descarga_auto: true,
  setpoint_pct: 50.0,
  nivel_pct: 0.0,
  nivel_cm: 0.0,
  nivel_v: 0.0,
  flow_v: 0.0,
  fill_pct: 0.0,
  discharge_pct: 35.0,
  fill_raw: 0,
  desc_raw: 0,
  sp_cm_raw: 0,
  pv_cm_raw: 0,
  kp: 3.2,
  ki: 0.25,
  kd: 1.8,
  t0: now,
  last_rx: 0,
  last_mqtt_ms: 0,
  registrando_csv: true,
  muestras_guardadas: 0,
  hist_t: [],
  hist_sp: [],
  hist_pv: [],
  hist_fill: [],
  hist_desc: [],
  csv_rows: ["timestamp,tiempo_s,modo_control,setpoint_pct,setpoint_cm,nivel_pct,nivel_cm,nivel_voltios,error_pct,fill_valve_pct,discharge_valve_pct,flow_voltios,kp,ki,kd"]
};

const topic = msg.topic || "";
const tag = topic.split("/").pop().split(".").pop();
const val = msg.payload;

if (val !== undefined && val !== null) {
  st.host = "192.168.1.10";
  st.port = 4840;
  st.conectado = true;
  st.last_rx = now;
  if (tag === "Nivel_Pct") st.nivel_pct = Number(val);
  else if (tag === "Nivel_CM") st.nivel_cm = Number(val);
  else if (tag === "Nivel_Voltios") st.nivel_v = Number(val);
  else if (tag === "Flow_Voltios") st.flow_v = Number(val);
  else if (tag === "Setpoint_Pct") st.setpoint_pct = Number(val);
  else if (tag === "Fill_Valve_Pct") st.fill_pct = Number(val);
  else if (tag === "Discharge_Valve_Pct") st.discharge_pct = Number(val);
  else if (tag === "Fill_Valve_Raw") st.fill_raw = Number(val);
  else if (tag === "Discharge_Valve_Raw") st.desc_raw = Number(val);
  else if (tag === "SP_Display_CM") st.sp_cm_raw = Number(val);
  else if (tag === "PV_Display_CM") st.pv_cm_raw = Number(val);
  else if (tag === "PID_Kp") st.kp = Number(val);
  else if (tag === "PID_Ki") st.ki = Number(val);
  else if (tag === "PID_Kd") st.kd = Number(val);
  else if (tag === "Modo_Control") st.modo = val ? "PID" : "MANUAL";
  else if (tag === "Usar_Pot_FIO") st.usar_pot_fio = Boolean(val);
  else if (tag === "Descarga_Auto") st.descarga_auto = Boolean(val);
  else if (tag === "DI_Start") st.di_start = Boolean(val);
  else if (tag === "DI_Stop") st.di_stop = Boolean(val);
  else if (tag === "DI_Modo_Local") {
    st.di_modo_local = Boolean(val);
    if (st.di_modo_local) st.usar_pot_fio = true;
  } else if (tag === "Sistema_Activo") {
    st.sistema_activo = Boolean(val);
  }
}

if (tag === "Sistema_Activo") {
  const t_s = Number(((now - st.t0) / 1000.0).toFixed(2));
  st.hist_t.push(t_s);
  st.hist_sp.push(Number(st.setpoint_pct.toFixed(2)));
  st.hist_pv.push(Number(st.nivel_pct.toFixed(2)));
  st.hist_fill.push(Number(st.fill_pct.toFixed(2)));
  st.hist_desc.push(Number(st.discharge_pct.toFixed(2)));
  if (st.hist_t.length > 600) {
    st.hist_t.shift(); st.hist_sp.shift(); st.hist_pv.shift(); st.hist_fill.shift(); st.hist_desc.shift();
  }
  const sp_cm = (st.setpoint_pct / 100.0) * 300.0;
  if (st.registrando_csv) {
    const err_pct = st.setpoint_pct - st.nivel_pct;
    const ts = new Date().toISOString().replace("T", " ").slice(0, 23);
    st.csv_rows.push([
      ts, t_s.toFixed(3), st.modo, st.setpoint_pct.toFixed(2), sp_cm.toFixed(2),
      st.nivel_pct.toFixed(2), st.nivel_cm.toFixed(2), st.nivel_v.toFixed(3),
      err_pct.toFixed(2), st.fill_pct.toFixed(2), st.discharge_pct.toFixed(2),
      st.flow_v.toFixed(3), st.kp.toFixed(4), st.ki.toFixed(4), st.kd.toFixed(4)
    ].join(","));
    if (st.csv_rows.length > 5000) st.csv_rows.splice(1, 1);
    st.muestras_guardadas = st.csv_rows.length - 1;
  }

  let mqttMsg = null;
  if (now - (st.last_mqtt_ms || 0) >= 1000) {
    st.last_mqtt_ms = now;
    mqttMsg = {
      topic: "planta/plc1756/datos",
      payload: {
        origen: "PLCnext_AXCF2152",
        modo: st.modo,
        sistema_activo: st.sistema_activo,
        di_start: st.di_start,
        di_stop: st.di_stop,
        usar_pot_fio: st.usar_pot_fio,
        setpoint_pct: Number(st.setpoint_pct.toFixed(2)),
        nivel_pct: Number(st.nivel_pct.toFixed(2)),
        nivel_cm: Number(st.nivel_cm.toFixed(2)),
        nivel_v: Number(st.nivel_v.toFixed(3)),
        flow_v: Number(st.flow_v.toFixed(3)),
        fill_valve_pct: Number(st.fill_pct.toFixed(2)),
        discharge_valve_pct: Number(st.discharge_pct.toFixed(2)),
        kp: st.kp,
        ki: st.ki,
        kd: st.kd,
        timestamp: new Date().toISOString()
      }
    };
  }

  let modbusWriteMsg = null;
  if (st.conectado && st.last_rx && (now - st.last_rx) < 3000) {
    const clamp16 = (v) => Math.max(0, Math.min(32767, Math.round(Number(v) || 0)));
    modbusWriteMsg = {
      payload: {
        value: [
          clamp16(st.fill_raw),
          clamp16(st.desc_raw),
          clamp16(st.sp_cm_raw),
          clamp16(st.pv_cm_raw)
        ],
        fc: 16,
        unitid: 1,
        address: 0,
        quantity: 4
      }
    };
  }

  global.set("tanque_state", st);
  return [mqttMsg, modbusWriteMsg];
}
global.set("tanque_state", st);
return [null, null];

const st = global.get("tanque_state") || {
  conectado: false, host: "192.168.1.10", port: 4840, modo: "PID",
  sistema_activo: true, di_start: false, di_stop: false,
  usar_pot_fio: false, descarga_auto: true, setpoint_pct: 50.0,
  nivel_pct: 0.0, nivel_cm: 0.0, nivel_v: 0.0, flow_v: 0.0,
  fill_pct: 0.0, discharge_pct: 35.0, kp: 3.2, ki: 0.25, kd: 1.8,
  t0: Date.now(), last_rx: 0, last_mqtt_ms: 0, registrando_csv: true, muestras_guardadas: 0,
  hist_t: [], hist_sp: [], hist_pv: [], hist_fill: [], hist_desc: [],
  csv_rows: ["timestamp,tiempo_s,modo_control,setpoint_pct,setpoint_cm,nivel_pct,nivel_cm,nivel_voltios,error_pct,fill_valve_pct,discharge_valve_pct,flow_voltios,kp,ki,kd"]
};
const p = msg.payload || {};

const writes = [];
const pushW = (tag, dtype, val) => writes.push({
  topic: "ns=6;s=Arp.Plc.Eclr/MainInstance." + tag + ";datatype=" + dtype,
  payload: val
});
if (p.setpoint_pct !== undefined) pushW("Setpoint_Pct", "Float", Math.max(0, Math.min(100, Number(p.setpoint_pct))));
if (p.usar_pot_fio !== undefined) pushW("Usar_Pot_FIO", "Boolean", Boolean(p.usar_pot_fio));
if (p.modo === "PID" || p.modo === "MANUAL") pushW("Modo_Control", "Boolean", p.modo === "PID");
if (p.sistema_activo !== undefined) pushW("Sistema_Activo", "Boolean", Boolean(p.sistema_activo));
if (p.descarga_auto !== undefined) pushW("Descarga_Auto", "Boolean", Boolean(p.descarga_auto));
if (p.discharge_base_pct !== undefined) pushW("Discharge_Base_Pct", "Float", Math.max(0, Math.min(100, Number(p.discharge_base_pct))));
if (p.fill_manual_pct !== undefined) pushW("Fill_Manual_Pct", "Float", Math.max(0, Math.min(100, Number(p.fill_manual_pct))));
if (p.kp !== undefined && p.ki !== undefined && p.kd !== undefined) {
  pushW("PID_Kp", "Float", Number(p.kp));
  pushW("PID_Ki", "Float", Number(p.ki));
  pushW("PID_Kd", "Float", Number(p.kd));
}

if (p.csv_action === "toggle") {
  st.registrando_csv = !st.registrando_csv;
} else if (p.csv_action === "reset") {
  st.t0 = Date.now();
  st.hist_t = []; st.hist_sp = []; st.hist_pv = []; st.hist_fill = []; st.hist_desc = [];
  st.csv_rows = [st.csv_rows[0]];
  st.muestras_guardadas = 0;
}
global.set("tanque_state", st);
const httpReply = { ...msg, payload: { ok: true }, headers: { "Content-Type": "application/json" } };
return [httpReply, writes];

const st = global.get("tanque_state") || { csv_rows: ["timestamp,tiempo_s,modo_control,setpoint_pct,setpoint_cm,nivel_pct,nivel_cm,nivel_voltios,error_pct,fill_valve_pct,discharge_valve_pct,flow_voltios,kp,ki,kd"] };
msg.payload = st.csv_rows.join("\n");
msg.headers = {
  "Content-Type": "text/csv; charset=utf-8",
  "Content-Disposition": "attachment; filename=\"registro_pid_tanque.csv\""
};
return msg;

let p = msg.payload;
if (typeof p === "string") {
  try { p = JSON.parse(p); } catch (e) { return null; }
}
if (!p || typeof p !== "object") return null;

const writes = [];
const pushW = (tag, dtype, val) => writes.push({
  topic: "ns=6;s=Arp.Plc.Eclr/MainInstance." + tag + ";datatype=" + dtype,
  payload: val
});
if (p.setpoint_pct !== undefined) pushW("Setpoint_Pct", "Float", Math.max(0, Math.min(100, Number(p.setpoint_pct))));
if (p.usar_pot_fio !== undefined) pushW("Usar_Pot_FIO", "Boolean", Boolean(p.usar_pot_fio));
if (p.modo === "PID" || p.modo === "MANUAL") pushW("Modo_Control", "Boolean", p.modo === "PID");
if (p.sistema_activo !== undefined) pushW("Sistema_Activo", "Boolean", Boolean(p.sistema_activo));
if (p.descarga_auto !== undefined) pushW("Descarga_Auto", "Boolean", Boolean(p.descarga_auto));
if (p.discharge_base_pct !== undefined) pushW("Discharge_Base_Pct", "Float", Math.max(0, Math.min(100, Number(p.discharge_base_pct))));
if (p.fill_manual_pct !== undefined) pushW("Fill_Manual_Pct", "Float", Math.max(0, Math.min(100, Number(p.fill_manual_pct))));
if (p.kp !== undefined && p.ki !== undefined && p.kd !== undefined) {
  pushW("PID_Kp", "Float", Number(p.kp));
  pushW("PID_Ki", "Float", Number(p.ki));
  pushW("PID_Kd", "Float", Number(p.kd));
}

return [writes];

if (!Array.isArray(msg.payload) || msg.payload.length < 3) return null;
const toInt16 = (v) => {
  const n = Number(v) & 0xFFFF;
  return n > 32767 ? n - 65536 : n;
};
const tags = ["Level_Meter_Raw", "Flow_Meter_Raw", "Setpoint_Pot_Raw"];
const writes = tags.map((t, i) => ({
  topic: "ns=6;s=Arp.Plc.Eclr/MainInstance." + t + ";datatype=Int16",
  payload: toInt16(msg.payload[i])
}));
return [writes];
